layers.shader:
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
void mainImage(out vec4 o, in vec2 f){
  vec2 R=iResolution.xy; vec2 jit=vec2(n(f*0.08+iTime*0.0), n(f*0.08+7.3))-0.5;
  vec2 uv=(f+jit*1.6)/R;
  vec3 c=texture(iChannel0,uv).rgb;
  float lum=dot(c,vec3(0.299,0.587,0.114));
  float ink=1.0-lum;                                   // how much ink is on this spot
  float speck=n(f*0.9)*0.6+n(f*0.23)*0.4;              // uneven ink density
  vec3 inked=mix(c, c+ (1.0-c)*0.18, smoothstep(0.35,0.95,speck)*ink);
  float fibre=n(vec2(f.x*0.05,f.y*0.9))*0.5+n(f*0.6)*0.5;
  vec3 paper=inked*(0.94+0.06*fibre);
  float grain=(h(f)-0.5)*0.03;
  o=vec4(paper+grain,1.0);
}
